CREATE TYPE audit_type AS ENUM ('INTERNAL','INSPECTION','SUPPLIER','PROCESS','COMPLIANCE','FOLLOW_UP');
CREATE TYPE audit_status AS ENUM ('DRAFT','PLANNED','IN_PREPARATION','IN_PROGRESS','FINDINGS_TO_CONSOLIDATE','REPORT_PREPARED','COMPLETED','CANCELLED');
CREATE TYPE finding_type AS ENUM ('CONFORMITY','OBSERVATION','IMPROVEMENT_OPPORTUNITY','POTENTIAL_NONCONFORMITY','CONFIRMED_NONCONFORMITY');
CREATE TYPE finding_severity AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL');
CREATE TYPE finding_status AS ENUM ('OPEN','UNDER_REVIEW','ACCEPTED','REFERRED_TO_ACTIONS','CLOSED');
CREATE TYPE audit_report_status AS ENUM ('DRAFT','IN_REVIEW','VALIDATED');
CREATE TYPE audit_item_result AS ENUM ('NOT_ASSESSED','CONFORMING','PARTIALLY_CONFORMING','NON_CONFORMING','NOT_APPLICABLE');

CREATE TABLE audit_programs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), code text NOT NULL, name text NOT NULL, period_start date NOT NULL, period_end date NOT NULL, objectives text NOT NULL, frequency_rationale text, coordinator_reference text, status text NOT NULL DEFAULT 'DRAFT', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, CONSTRAINT audit_programs_org_code_unique UNIQUE (organization_id, code));
CREATE TABLE audits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), program_id uuid REFERENCES audit_programs(id), organization_id uuid NOT NULL REFERENCES organizations(id), process_id uuid REFERENCES processes(id), reference text NOT NULL, title text NOT NULL, type audit_type NOT NULL, objectives text NOT NULL, scope text NOT NULL, criteria text NOT NULL, planned_start date NOT NULL, planned_end date NOT NULL, actual_start date, actual_end date, team_references text, status audit_status NOT NULL DEFAULT 'DRAFT', notes text, conclusion text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, CONSTRAINT audits_org_reference_unique UNIQUE (organization_id, reference));
CREATE TABLE audit_processes (audit_id uuid NOT NULL REFERENCES audits(id), process_id uuid NOT NULL REFERENCES processes(id), PRIMARY KEY (audit_id, process_id));
CREATE TABLE audit_requirements (audit_id uuid NOT NULL REFERENCES audits(id), requirement_id uuid NOT NULL REFERENCES requirements(id), PRIMARY KEY (audit_id, requirement_id));
CREATE TABLE audit_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), audit_id uuid NOT NULL REFERENCES audits(id), code text NOT NULL, domain text NOT NULL, question text NOT NULL, criteria text NOT NULL, process_id uuid REFERENCES processes(id), requirement_id uuid REFERENCES requirements(id), owner_reference text, result audit_item_result NOT NULL DEFAULT 'NOT_ASSESSED', observation text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, CONSTRAINT audit_items_audit_code_unique UNIQUE (audit_id, code));
CREATE TABLE audit_findings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), audit_id uuid NOT NULL REFERENCES audits(id), reference text NOT NULL, type finding_type NOT NULL, description text NOT NULL, criterion text, evidence_reference text, severity finding_severity NOT NULL, process_id uuid REFERENCES processes(id), requirement_id uuid REFERENCES requirements(id), risk_id uuid REFERENCES risks(id), status finding_status NOT NULL DEFAULT 'OPEN', recommendation text, corrective_action_reference text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, CONSTRAINT audit_findings_audit_reference_unique UNIQUE (audit_id, reference));
CREATE TABLE audit_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), audit_id uuid NOT NULL REFERENCES audits(id), summary text NOT NULL, performed_scope text NOT NULL, method text NOT NULL, findings_summary text NOT NULL, conclusion text NOT NULL, recommendations text, finalized_at timestamptz, status audit_report_status NOT NULL DEFAULT 'DRAFT', validation_reference text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, CONSTRAINT audit_reports_audit_unique UNIQUE (audit_id));
CREATE INDEX audits_status_idx ON audits(status); CREATE INDEX audits_period_idx ON audits(planned_start, planned_end); CREATE INDEX audit_items_audit_idx ON audit_items(audit_id); CREATE INDEX audit_findings_status_idx ON audit_findings(status);
ALTER TABLE audit_programs ENABLE ROW LEVEL SECURITY; ALTER TABLE audits ENABLE ROW LEVEL SECURITY; ALTER TABLE audit_processes ENABLE ROW LEVEL SECURITY; ALTER TABLE audit_requirements ENABLE ROW LEVEL SECURITY; ALTER TABLE audit_items ENABLE ROW LEVEL SECURITY; ALTER TABLE audit_findings ENABLE ROW LEVEL SECURITY; ALTER TABLE audit_reports ENABLE ROW LEVEL SECURITY;
-- No permissive policies are created. Server-side access requires the existing privileged database path.
